        T = max(0.05, T * 0.9998)
        if cur == 0:
            break
    print("restart", restart, "cost", cur, flush=True)
    if cur == 0:
        best_overall = X
        break
if best_overall:
    for p in PAIRS:
        print(p, best_overall[p])
    pickle.dump(best_overall, open("designs/anneal_sol.pkl", "wb"))
else:
    print("none")
